#!/usr/bin/env python3
"""Run every Ruptura simulation directory generated by ``generate.py``.

    python run.py                 # run everything under simulations/
    python run.py simulations/figure_1b_breakthrough_298K
    python run.py --rerun -j 4    # force a rerun with four workers
    python run.py --max-hours 8   # allow each simulation up to eight hours

Set RUPTURA_BIN to use a binary other than ../../../build/ruptura.

Each simulation is killed once it exceeds ``--max-hours`` (default 4 h) of wall time;
the script then reports it as unfinished and exits with a non-zero status.
"""

from __future__ import annotations

import argparse
import json
import os
import subprocess
from concurrent.futures import ThreadPoolExecutor, as_completed
from pathlib import Path

ROOT = Path(__file__).resolve().parent
RUPTURA_BINARY = Path(os.environ.get("RUPTURA_BIN", ROOT.parents[2] / "build" / "ruptura")).resolve()
MAX_HOURS = 4.0


def find_simulation_dirs(paths: list[Path]) -> list[Path]:
    directories = set()
    for path in paths:
        if (path / "simulation.json").is_file():
            directories.add(path.resolve())
        directories.update(match.parent.resolve() for match in path.rglob("simulation.json"))
    return sorted(directories)


def has_finished(directory: Path) -> bool:
    """Whether this directory already holds a complete result.

    A finished breakthrough prints ``Final time:``.  A MixturePrediction log has no
    such marker and its startup banner already contains most words the run prints
    later, so completeness is judged from the output instead: one row per requested
    pressure point.
    """

    log = directory / "run.log"
    if not log.is_file():
        return False

    settings = json.loads((directory / "simulation.json").read_text())
    if settings["SimulationType"] == "Breakthrough":
        return "Final time:" in log.read_text()

    written = sorted(directory.glob("component_*.data"))
    if not written:
        return False
    rows = sum(
        1
        for line in written[0].read_text().splitlines()
        if line.strip() and not line.startswith("#")
    )
    return rows >= settings["NumberOfPressurePoints"]


def run_ruptura(directory: Path, max_seconds: float) -> dict:
    print(f"running {directory.relative_to(ROOT)}", flush=True)
    with (directory / "run.log").open("w") as log:
        try:
            result = subprocess.run(
                [str(RUPTURA_BINARY)],
                cwd=directory,
                stdout=log,
                stderr=subprocess.STDOUT,
                text=True,
                timeout=max_seconds,
            )
        except subprocess.TimeoutExpired:
            log.write(f"\nWARNING: killed after exceeding {max_seconds / 3600:g} h; simulation unfinished\n")
            return {"directory": directory, "returncode": None, "timed_out": True}
    return {"directory": directory, "returncode": result.returncode, "timed_out": False}


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("dirs", nargs="*", type=Path, default=[ROOT / "simulations"])
    parser.add_argument("--rerun", action="store_true", help="rerun simulations that already finished")
    parser.add_argument("-j", "--workers", type=int, default=8)
    parser.add_argument(
        "--max-hours", type=float, default=MAX_HOURS, help="wall-time limit per simulation in hours"
    )
    arguments = parser.parse_args()

    if not RUPTURA_BINARY.is_file():
        raise SystemExit(f"Ruptura binary not found at {RUPTURA_BINARY}")

    directories = find_simulation_dirs([Path(p) for p in arguments.dirs])
    if not directories:
        raise SystemExit("no simulation directories found; run generate.py first")

    pending = [d for d in directories if arguments.rerun or not has_finished(d)]
    skipped = len(directories) - len(pending)
    if skipped:
        print(f"skipping {skipped} finished simulation(s); use --rerun to force")
    if not pending:
        print("nothing to run")
        return

    max_seconds = arguments.max_hours * 3600.0
    failures = []
    timeouts = []
    with ThreadPoolExecutor(max_workers=arguments.workers) as executor:
        futures = {executor.submit(run_ruptura, d, max_seconds): d for d in pending}
        for future in as_completed(futures):
            result = future.result()
            if result["timed_out"]:
                status = f"TIMEOUT (> {arguments.max_hours:g} h)"
                timeouts.append(result["directory"])
            elif result["returncode"] == 0:
                status = "ok"
            else:
                status = f"FAILED ({result['returncode']})"
                failures.append(result["directory"])
            print(f"{status}: {result['directory'].relative_to(ROOT)}", flush=True)

    unfinished = len(failures) + len(timeouts)
    print(f"\n{len(pending) - unfinished}/{len(pending)} simulations completed")
    for directory in failures:
        print(f"  failed: {directory.relative_to(ROOT)}")
    for directory in timeouts:
        print(f"  WARNING unfinished (exceeded {arguments.max_hours:g} h): {directory.relative_to(ROOT)}")
    if unfinished:
        raise SystemExit(f"{unfinished} simulation(s) did not finish")


if __name__ == "__main__":
    main()
